router4.get("/responses-summary/:year/:month", authenticateToken, requireRole(["gestor", "coordenador"]), async (req, res) => {
  const params = parseYearMonthParams(req, res);
  if (!params) return;
  const { year, month } = params;
  try {
    if (!db) {
      return res.status(503).json({ error: "Database service unavailable" });
    }
    const [template] = await db.select().from(questionnaires).where(and4(
      eq9(questionnaires.month, month),
      eq9(questionnaires.year, year)
    )).limit(1);
    if (!template) {
      return res.status(404).json({ error: "Template not found" });
    }
    const responses = await db.select().from(questionnaireResponses).where(eq9(questionnaireResponses.questionnaireId, template.id));
    const summary = {};
    const questions = template.questions;
    responses.forEach((response) => {
      let parsedResponses;
      try {
        parsedResponses = JSON.parse(response.responses);
        if (!Array.isArray(parsedResponses)) return;
      } catch {
        console.warn("[QUESTIONNAIRE] Failed to parse response:", response.id);
        return;
      }
      parsedResponses.forEach((resp) => {
        if (!summary[resp.questionId]) {
          summary[resp.questionId] = {};
        }
        const answer = resp.answer;
        if (typeof answer === "object" && !Array.isArray(answer) && "answer" in answer) {
          const mainAnswer = answer.answer;
          if (!summary[resp.questionId][mainAnswer]) {
            summary[resp.questionId][mainAnswer] = 0;
          }
          summary[resp.questionId][mainAnswer]++;
          if (answer.sub) {
            const subKey = `${resp.questionId}_sub`;
            if (!summary[subKey]) {
              summary[subKey] = {};
            }
            if (!summary[subKey][answer.sub]) {
              summary[subKey][answer.sub] = 0;
            }
            summary[subKey][answer.sub]++;
          }
        } else if (Array.isArray(answer)) {
          answer.forEach((option) => {
            if (!summary[resp.questionId][option]) {
              summary[resp.questionId][option] = 0;
            }
            summary[resp.questionId][option]++;
          });
        } else if (typeof answer === "string") {
          if (!summary[resp.questionId][answer]) {
            summary[resp.questionId][answer] = 0;
          }
          summary[resp.questionId][answer]++;
        }
      });
    });
    res.json({
      totalResponses: responses.length,
      questions,
      summary
    });
  } catch (error) {
    console.error("Error fetching response summary:", error);
    res.status(500).json({ error: "Failed to fetch response summary" });
  }
});
