  const massTimesWithMostChanges = Array.from(massTimeChanges.entries()).map(([time2, count14]) => ({ time: time2, changeCount: count14 })).sort((a, b) => b.changeCount - a.changeCount).slice(0, 5);
  let algorithmHealth;
