  recipientIds: z6.array(z6.string()).optional(),
  // IDs específicos ou vazio para todos
  recipientRole: z6.enum(["ministro", "coordenador", "coordenador_comunidade", "coordenador_paroquial", "gestor", "reitor", "all"]).optional(),
