import * as XLSX2 from "xlsx";
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";
function exportToExcel(data) {
  const workbook = XLSX2.utils.book_new();
  const wsData = [];
  wsData.push([data.title]);
  if (data.subtitle) wsData.push([data.subtitle]);
  wsData.push([`Gerado em: ${data.generatedAt}`]);
  if (data.period) wsData.push([`Per\xEDodo: ${data.period}`]);
  wsData.push([]);
  if (data.summary && data.summary.length > 0) {
    wsData.push(["RESUMO"]);
    data.summary.forEach((item) => {
      wsData.push([item.label, item.value]);
    });
    wsData.push([]);
  }
  wsData.push(data.headers);
  data.rows.forEach((row) => {
    wsData.push(row);
  });
  const worksheet = XLSX2.utils.aoa_to_sheet(wsData);
  const colWidths = data.headers.map((header, i) => {
    const maxLength = Math.max(
      header.length,
      ...data.rows.map((row) => String(row[i] || "").length)
    );
    return { wch: Math.min(Math.max(maxLength + 2, 10), 50) };
  });
  worksheet["!cols"] = colWidths;
  XLSX2.utils.book_append_sheet(workbook, worksheet, "Relat\xF3rio");
  const buffer = XLSX2.write(workbook, { type: "buffer", bookType: "xlsx" });
  return buffer;
}
function exportToPDF(data) {
  const doc = new jsPDF({
    orientation: "portrait",
    unit: "mm",
    format: "a4"
  });
  const pageWidth = doc.internal.pageSize.getWidth();
  let yPosition = 20;
  doc.setFontSize(18);
  doc.setFont("helvetica", "bold");
  doc.text(data.title, pageWidth / 2, yPosition, { align: "center" });
  yPosition += 8;
  if (data.subtitle) {
    doc.setFontSize(12);
    doc.setFont("helvetica", "normal");
    doc.text(data.subtitle, pageWidth / 2, yPosition, { align: "center" });
    yPosition += 6;
  }
  doc.setFontSize(10);
  doc.setTextColor(100);
  doc.text(`Gerado em: ${data.generatedAt}`, pageWidth / 2, yPosition, { align: "center" });
  yPosition += 4;
  if (data.period) {
    doc.text(`Per\xEDodo: ${data.period}`, pageWidth / 2, yPosition, { align: "center" });
    yPosition += 4;
  }
  yPosition += 6;
  if (data.summary && data.summary.length > 0) {
    doc.setTextColor(0);
    doc.setFontSize(12);
    doc.setFont("helvetica", "bold");
    doc.text("Resumo", 14, yPosition);
    yPosition += 6;
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    data.summary.forEach((item) => {
      doc.text(`${item.label}: ${item.value}`, 14, yPosition);
      yPosition += 5;
    });
    yPosition += 6;
  }
  if (data.rows.length > 0) {
    autoTable(doc, {
      head: [data.headers],
      body: data.rows.map((row) => row.map((cell) => String(cell))),
      startY: yPosition,
      styles: {
        fontSize: 9,
        cellPadding: 3
      },
      headStyles: {
        fillColor: [180, 115, 51],
        // Bronze/copper color
        textColor: 255,
        fontStyle: "bold"
      },
      alternateRowStyles: {
        fillColor: [250, 248, 243]
        // Light cream
      },
      margin: { left: 14, right: 14 }
    });
  }
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(
      `MESC - Santu\xE1rio S\xE3o Judas Tadeu | P\xE1gina ${i} de ${pageCount}`,
      pageWidth / 2,
      doc.internal.pageSize.getHeight() - 10,
      { align: "center" }
    );
  }
  const arrayBuffer = doc.output("arraybuffer");
  return Buffer.from(arrayBuffer);
}
function exportToCSV(data) {
  const lines = [];
  const BOM = "\uFEFF";
  lines.push(`# ${data.title}`);
  if (data.subtitle) lines.push(`# ${data.subtitle}`);
  lines.push(`# Gerado em: ${data.generatedAt}`);
  if (data.period) lines.push(`# Per\xEDodo: ${data.period}`);
  lines.push("");
  if (data.summary && data.summary.length > 0) {
    lines.push("# RESUMO");
    data.summary.forEach((item) => {
      lines.push(`# ${item.label}: ${item.value}`);
    });
    lines.push("");
  }
  lines.push(data.headers.map((h) => `"${h}"`).join(","));
  data.rows.forEach((row) => {
    lines.push(row.map((cell) => {
      const value = String(cell);
      if (value.includes(",") || value.includes('"') || value.includes("\n")) {
        return `"${value.replace(/"/g, '""')}"`;
      }
      return value;
    }).join(","));
  });
  return BOM + lines.join("\n");
}
function getMimeType(format13) {
  switch (format13) {
    case "xlsx":
      return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
    case "pdf":
      return "application/pdf";
    case "csv":
      return "text/csv; charset=utf-8";
    default:
      return "application/octet-stream";
  }
}
function getFileExtension(format13) {
  return format13;
}

