import { Router as Router19 } from "express";
import { eq as eq32, and as and23, gte as gte15, lte as lte13, sql as sql17, or as or9, isNull as isNull3, count as count7, desc as desc10, inArray as inArray14 } from "drizzle-orm";
import { format as format10, addDays as addDays6, subDays, startOfMonth as startOfMonth4, endOfMonth as endOfMonth4 } from "date-fns";
var router19 = Router19();
router19.get("/urgent-alerts", async (req, res) => {
  try {
    const now = /* @__PURE__ */ new Date();
    const next48Hours = addDays6(now, 2);
    const next7Days = addDays6(now, 7);
    const incompleteMasses = await db.select({
      date: schedules.date,
      time: schedules.time,
      totalSlots: sql17`COUNT(*)`,
      filledSlots: sql17`COUNT(CASE WHEN ${schedules.ministerId} IS NOT NULL THEN 1 END)`,
      vacancies: sql17`COUNT(CASE WHEN ${schedules.ministerId} IS NULL THEN 1 END)`
    }).from(schedules).where(
      and23(
        eq32(schedules.status, "published"),
        gte15(schedules.date, format10(now, "yyyy-MM-dd")),
        lte13(schedules.date, format10(next7Days, "yyyy-MM-dd"))
      )
    ).groupBy(schedules.date, schedules.time).having(sql17`COUNT(CASE WHEN ${schedules.ministerId} IS NULL THEN 1 END) > 0`);
    const criticalMasses = incompleteMasses.filter((mass) => {
      const massDate = /* @__PURE__ */ new Date(mass.date + "T12:00:00");
      return massDate <= next48Hours;
    }).map((m) => ({
      ...m,
      hoursUntil: Math.round(((/* @__PURE__ */ new Date(m.date + "T12:00:00")).getTime() - now.getTime()) / (1e3 * 60 * 60)),
      massTime: m.time
    }));
    const regularIncomplete = incompleteMasses.filter((mass) => {
      const massDate = /* @__PURE__ */ new Date(mass.date + "T12:00:00");
      return massDate > next48Hours;
    }).map((m) => ({
      ...m,
      massTime: m.time
    }));
    const pendingSubstitutions = await db.select({
      id: substitutionRequests.id,
      scheduleId: substitutionRequests.scheduleId,
      requesterId: substitutionRequests.requesterId,
      requesterName: users.name,
      reason: substitutionRequests.reason,
      status: substitutionRequests.status,
      massDate: schedules.date,
      massTime: schedules.time
    }).from(substitutionRequests).innerJoin(users, eq32(substitutionRequests.requesterId, users.id)).innerJoin(schedules, eq32(substitutionRequests.scheduleId, schedules.id)).where(
      and23(
        eq32(schedules.status, "published"),
        or9(
          eq32(substitutionRequests.status, "pending"),
          eq32(substitutionRequests.status, "available")
        ),
        gte15(schedules.date, format10(now, "yyyy-MM-dd"))
      )
    ).orderBy(schedules.date);
    const urgentSubstitutions = pendingSubstitutions.filter((sub) => {
      const subDate = /* @__PURE__ */ new Date(sub.massDate + "T12:00:00");
      return subDate <= next48Hours;
    }).map((s) => ({
      ...s,
      hoursUntil: Math.round(((/* @__PURE__ */ new Date(s.massDate + "T12:00:00")).getTime() - now.getTime()) / (1e3 * 60 * 60))
    }));
    const regularSubstitutions = pendingSubstitutions.filter((sub) => {
      const subDate = /* @__PURE__ */ new Date(sub.massDate + "T12:00:00");
      return subDate > next48Hours;
    });
    res.json({
      success: true,
      data: {
        criticalMasses,
        incompleteMasses: regularIncomplete,
        urgentSubstitutions,
        pendingSubstitutions: regularSubstitutions,
        totalAlerts: criticalMasses.length + urgentSubstitutions.length
      }
    });
  } catch (error) {
    console.error("[DASHBOARD_ALERTS] Error:", error);
    res.status(500).json({ success: false, error: "Failed to fetch urgent alerts" });
  }
});
router19.get("/next-week-masses", async (req, res) => {
  try {
    const now = /* @__PURE__ */ new Date();
    const next7Days = addDays6(now, 7);
    const masses = await db.select({
      date: schedules.date,
      massTime: schedules.time,
      totalSlots: sql17`COUNT(*)`,
      totalAssigned: sql17`COUNT(CASE WHEN ${schedules.ministerId} IS NOT NULL THEN 1 END)`,
      totalVacancies: sql17`COUNT(CASE WHEN ${schedules.ministerId} IS NULL THEN 1 END)`,
      requiredMinisters: sql17`COUNT(*)`,
      // All slots are required
      hasPendingSubstitutions: sql17`EXISTS(
          SELECT 1 FROM ${substitutionRequests}
          WHERE ${substitutionRequests.scheduleId} IN (
            SELECT id FROM ${schedules} AS s2
            WHERE s2.date = ${schedules.date} AND s2.time = ${schedules.time}
          )
          AND ${substitutionRequests.status} IN ('pending', 'available')
        )`
    }).from(schedules).where(
      and23(
        eq32(schedules.status, "published"),
        gte15(schedules.date, format10(now, "yyyy-MM-dd")),
        lte13(schedules.date, format10(next7Days, "yyyy-MM-dd"))
      )
    ).groupBy(schedules.date, schedules.time).orderBy(schedules.date, schedules.time);
    const massesWithStatus = masses.map((mass) => {
      const staffingRate = mass.requiredMinisters > 0 ? mass.totalAssigned / mass.requiredMinisters * 100 : 0;
      let status = "full";
      if (staffingRate < 80) status = "critical";
      else if (staffingRate < 100) status = "warning";
      const id = `${mass.date}-${mass.massTime}`;
      return {
        id,
        date: mass.date,
        massTime: mass.massTime,
        totalAssigned: mass.totalAssigned,
        totalVacancies: mass.totalVacancies,
        requiredMinisters: mass.requiredMinisters,
        staffingRate: Math.round(staffingRate),
        status,
        hasPendingSubstitutions: mass.hasPendingSubstitutions
      };
    });
    res.json({
      success: true,
      data: massesWithStatus
    });
  } catch (error) {
    console.error("[DASHBOARD_NEXT_WEEK] Error:", error);
    res.status(500).json({ success: false, error: "Failed to fetch next week masses" });
  }
});
